/* Verdict premium R40 : classe posée avant le premier rendu. ?premium=off la retire. */(function(d,s){try{var q=new URLSearchParams(location.search+(self.__vdq||"")).get("premium");if(q==="off")localStorage.setItem("verdict.premium","off");else if(q==="on")localStorage.removeItem("verdict.premium");if(localStorage.getItem("verdict.premium")==="off")return;}catch(e){}d.documentElement.classList.add("p40","p40-"+s);d.documentElement.setAttribute("data-p40-surface",s);})(document,"app");